function* even(n) { return n === 0 ? true : yield odd(n - 1); }
function* odd(n)  { return n === 0 ? false : yield even(n - 1); }

function run(gen) {                 // iterative driver over a generator stack
    const stack = [gen];
    let out;
    while (stack.length) {
        const step = stack[stack.length - 1].next(out);
        if (step.done) { stack.pop(); out = step.value; }
        else stack.push(step.value);
    }
    return out;
}
